{
  "id": "p_000",
  "summary": "Minimal REST API specification for task management, delivered as a single valid JSON document defining CRUD endpoints, explicit JSON schemas, and standard HTTP status codes.",
  "approach": "Construct a centralized JSON document containing a `schemas` object for reusable payload definitions and an `endpoints` array mapping exactly five routes to HTTP methods, request bodies, and response schemas. Enforce strict REST conventions by using POST for creation (201), GET for retrieval (200), PATCH for partial updates (200), and DELETE for removal (204). Standardize error handling with a consistent `{error: {code, message}}` structure mapped to 400/404 status codes. All types, required flags, and enum constraints are explicitly declared using JSON Schema-compatible notation.",
  "tradeoffs": [
    "Omits OpenAPI metadata to strictly satisfy the minimal scope constraint, requiring manual integration with API gateways or documentation generators.",
    "Relies on JSON Schema draft-07 conventions for type validation rather than a formal specification standard like OpenAPI 3.0.",
    "Uses `$ref` pointers which require a resolver for runtime validation or client generation."
  ],
  "evidence": [
    "RFC 7231 (HTTP/1.1 Semantics and Content) for standard methods and status codes.",
    "JSON Schema Draft 07 for payload structure and validation rules.",
    "RFC 3339 / ISO 8601 for `created_at` and `updated_at` timestamp formatting."
  ],
  "artifacts": [
    {
      "kind": "api_spec.json",
      "language": "json",
      "source": "{
  "api_version": "1.0",
  "schemas": {
    "Task": {
      "type": "object",
      "required": ["id", "title", "status", "created_at", "updated_at"],
      "properties": {
        "id": { "type": "string" },
        "title": { "type": "string" },
        "description": { "type": "string" },
        "status": { "type": "string", "enum": ["pending", "in_progress", "completed"] },
        "created_at": { "type": "string", "format": "date-time" },
        "updated_at": { "type": "string", "format": "date-time" }
      }
    },
    "Error": {
      "type": "object",
      "required": ["error"],
      "properties": {
        "error": {
          "type": "object",
          "required": ["code", "message"],
          "properties": {
            "code": { "type": "string" },
            "message": { "type": "string" }
          }
        }
      }
    }
  },
  "endpoints": [
    {
      "method": "POST",
      "path": "/v1/tasks",
      "request_body": { "$ref": "#/schemas/Task" },
      "responses": {
        "201": { "body": { "$ref": "#/schemas/Task" } },
        "400": { "body": { "$ref": "#/schemas/Error" } }
      }
    },
    {
      "method": "GET",
      "path": "/v1/tasks",
      "request_body": null,
      "responses": {
        "200": { "body": { "type": "array", "items": { "$ref": "#/schemas/Task" } } },
        "400": { "body": { "$ref": "#/schemas/Error" } }
      }
    },
    {
      "method": "GET",
      "path": "/v1/tasks/{id}",
      "request_body": null,
      "responses": {
        "200": { "body": { "$ref": "#/schemas/Task" } },
        "404": { "body": { "$ref": "#/schemas/Error" } }
      }
    },
    {
      "method": "PATCH",
      "path": "/v1/tasks/{id}",
      "request_body": {
        "type": "object",
        "properties": {
          "title": { "type": "string" },
          "description": { "type": "string" },
          "status": { "type": "string", "enum": ["pending", "in_progress", "completed"] }
        }
      },
      "responses": {
        "200": { "body": { "$ref": "#/schemas/Task" } },
        "400": { "body": { "$ref": "#/schemas/Error" } },
        "404": { "body": { "$ref": "#/schemas/Error" } }
      }
    },
    {
      "method": "DELETE",
      "path": "/v1/tasks/{id}",
      "request_body": null,
      "responses": {
        "204": { "body": null },
        "404": { "body": { "$ref": "#/schemas/Error" } }
      }
    }
  ]
}"
